import ToolbarButton from "./ToolbarButton";
import useModal from "../hooks/useModal";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { useState, useRef, useEffect } from "react";
import { REDO_COMMAND, UNDO_COMMAND, CUT_COMMAND, COPY_COMMAND } from "lexical";
import "./Toolbar.css";
import { getUsjMarkerAction } from "../adaptors/usj-marker-action.utils";
import { InsertDialog } from "./Input/TextInput";
import { ScriptureReference } from "shared/utils/get-marker-action.model";
import { ViewOptions } from "../adaptors/view-options.utils";
import { pasteSelection, pasteSelectionAsPlainText } from "shared-react/plugins/clipboard.utils";
import { InsertFunction } from "./Input/TextInput";
import BCVSelector from "./BCV/BCVSelector";

export const Toolbar = ({
  scrRef,
  viewOptions,
  autoNumbering = false,
  canUndo,
  canRedo,
  setScrRef,
  scope,
  // readOnly,
}: {
  scrRef: ScriptureReference;
  viewOptions?: ViewOptions;
  autoNumbering?: boolean;
  canUndo: boolean;
  canRedo: boolean;
  setScrRef: React.Dispatch<React.SetStateAction<ScriptureReference>>;
  scope?: {
    availableBooks: Set<string>;
  };
  // readOnly: boolean;
}) => {
  const [modal, showModal] = useModal();
  const [isInsertDropdownOpen, setIsInsertDropdownOpen] = useState(false);
  const [isClipboardDropdownOpen, setIsClipboardDropdownOpen] = useState(false);
  const insertDropdownRef = useRef<HTMLDivElement>(null);
  const clipboardDropdownRef = useRef<HTMLDivElement>(null);
  const [editor] = useLexicalComposerContext();
  const [isEditable, setIsEditable] = useState(true);
  const editorContainerRef = useRef<HTMLDivElement | null>(null);

  type InsertOption = {
    title: string;
    marker: string;
    requiresValue: boolean;
    placeholder?: string;
  };

  type ClipboardOption = {
    title: string;
    action: () => void;
  };

  const insertOptions: InsertOption[] = [
    {
      title: "Verse",
      marker: "v",
      requiresValue: true,
      placeholder: "Verse Number",
    },
    {
      title: "Chapter",
      marker: "c",
      requiresValue: true,
      placeholder: "Chapter Number",
    },
    {
      title: "Footnote",
      marker: "f",
      requiresValue: true,
    },
    {
      title: "Cross Reference",
      marker: "x",
      requiresValue: true,
    },
  ];

  const clipboardOptions: ClipboardOption[] = [
    {
      title: "Cut",
      action: handleCut,
    },
    {
      title: "Copy",
      action: handleCopy,
    },
    {
      title: "Paste",
      action: handlePaste,
    },
    {
      title: "Paste as Plain Text",
      action: handlePasteAsPlainText,
    },
  ];

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (insertDropdownRef.current && !insertDropdownRef.current.contains(event.target as Node)) {
        setIsInsertDropdownOpen(false);
      }
      if (
        clipboardDropdownRef.current &&
        !clipboardDropdownRef.current.contains(event.target as Node)
      ) {
        setIsClipboardDropdownOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  useEffect(() => {
    const editorElement = document.querySelector(".editor-input");
    if (editorElement) {
      const container = editorElement.closest("div");
      editorContainerRef.current = container as HTMLDivElement;
    }
  }, []);

  function handleCopy() {
    editor.dispatchCommand(COPY_COMMAND, null);
  }

  function handleCut() {
    editor.dispatchCommand(CUT_COMMAND, null);
  }

  function handlePaste() {
    pasteSelection(editor);
  }

  function handlePasteAsPlainText() {
    pasteSelectionAsPlainText(editor);
  }

  function handleUndo() {
    editor.dispatchCommand(UNDO_COMMAND, undefined);
  }

  function handleRedo() {
    editor.dispatchCommand(REDO_COMMAND, undefined);
  }

  function handleInsertOption(option: InsertOption) {
    console.log({ option });
    setIsInsertDropdownOpen(false);

    if (option.requiresValue) {
      showModal(`Insert ${option.title}`, (onClose) => (
        <InsertDialog
          activeEditor={editor}
          onClose={onClose}
          label={option.title}
          placeholder={option.placeholder}
          insertFunction={({ editor, value, noteText }: InsertFunction) => {
            const markerAction = getUsjMarkerAction(option.marker, undefined, viewOptions);
            if (markerAction && markerAction.action) {
              markerAction.action({
                reference: scrRef,
                editor: editor,
                autoNumbering: autoNumbering,
                newVerseRChapterNum: value ? parseInt(value) : undefined,
                noteText: noteText,
              });
            }
          }}
        />
      ));
    } else {
      const markerAction = getUsjMarkerAction(option.marker, undefined, viewOptions);
      if (markerAction && markerAction.action) {
        markerAction.action({
          reference: scrRef,
          editor: editor,
          autoNumbering: autoNumbering,
        });
      }
    }
  }

  function handleClipboardOption(option: ClipboardOption) {
    setIsClipboardDropdownOpen(false);
    option.action();
  }

  return (
    <div className="scribe-toolbar scribe-toolbar-sticky">
      <div className="scribe-toolbar-group">
        <ToolbarButton onClick={handleUndo} title="Undo" disabled={!canUndo}>
          Undo
        </ToolbarButton>
        <ToolbarButton onClick={handleRedo} title="Redo" disabled={!canRedo}>
          Redo
        </ToolbarButton>
      </div>

      <div className="scribe-toolbar-group">
        <BCVSelector scrRef={scrRef} setScrRef={setScrRef} scope={scope} />
      </div>

      {/* Regular clipboard buttons for desktop */}
      <div className="scribe-toolbar-group clipboard-actions-responsive">
        <ToolbarButton onClick={handleCut} title="Cut">
          Cut
        </ToolbarButton>
        <ToolbarButton onClick={handleCopy} title="Copy">
          Copy
        </ToolbarButton>
        <ToolbarButton onClick={handlePaste} title="Paste">
          Paste
        </ToolbarButton>
        <ToolbarButton onClick={handlePasteAsPlainText} title="Paste as Plain Text">
          Paste as Plain Text
        </ToolbarButton>
      </div>

      {/* Clipboard dropdown for mobile */}
      <div className="scribe-toolbar-group clipboard-dropdown" ref={clipboardDropdownRef}>
        <ToolbarButton
          onClick={() => setIsClipboardDropdownOpen(!isClipboardDropdownOpen)}
          className={isClipboardDropdownOpen ? "scribe-active" : ""}
        >
          Edit ▼
        </ToolbarButton>

        {isClipboardDropdownOpen && (
          <div className="scribe-dropdown">
            {clipboardOptions.map((option) => (
              <button
                key={option.title}
                className="scribe-dropdown-item"
                onClick={() => handleClipboardOption(option)}
              >
                {option.title}
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="scribe-toolbar-group" ref={insertDropdownRef}>
        <ToolbarButton
          onClick={() => setIsInsertDropdownOpen(!isInsertDropdownOpen)}
          className={isInsertDropdownOpen ? "scribe-active" : ""}
        >
          Insert ▼
        </ToolbarButton>

        {isInsertDropdownOpen && (
          <div className="scribe-dropdown">
            {insertOptions.map((option) => (
              <button
                key={option.title}
                className="scribe-dropdown-item"
                onClick={() => handleInsertOption(option)}
              >
                {option.title}
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="scribe-toolbar-group">
        <ToolbarButton
          onClick={() => {
            const newValue = !isEditable;
            setIsEditable(newValue);
            editor.setEditable(newValue);
          }}
          className={isEditable ? "scribe-status-editable" : "scribe-status-readonly"}
        >
          {isEditable ? "Editable" : "Read Only"}
        </ToolbarButton>
      </div>
      {modal}
    </div>
  );
};

export default Toolbar;
