import { useState, useCallback, useEffect, useRef } from "react";
// import { ChevronDown, ChevronLeft } from "lucide-react";
import { bibleData, getBook, getChapterCount } from "./bible66Data";
import "./BCVSelector.css";

interface ScriptureReference {
  book: string;
  chapterNum: number;
  verseNum: number;
}

interface Scope {
  availableBooks: Set<string>;
}

interface BCVSelectorProps {
  scrRef: ScriptureReference;
  setScrRef: (ref: ScriptureReference) => void;
  scope?: Scope;
}

export default function BCVSelector({ scrRef, setScrRef, scope }: BCVSelectorProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [stage, setStage] = useState<"books" | "chapters">("books");
  const [selectedBook, setSelectedBook] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<"OT" | "NT">("OT");
  const dropdownRef = useRef<HTMLDivElement>(null);

  const isBookAvailable = useCallback(
    (bookCode: string) => (scope ? scope.availableBooks.has(bookCode) : true),
    [scope],
  );

  const handleBookClick = (bookCode: string) => {
    setSelectedBook(bookCode);
    setStage("chapters");
  };

  const handleChapterClick = (chapterNum: number) => {
    if (selectedBook) {
      setScrRef({
        book: selectedBook,
        chapterNum,
        verseNum: 1,
      });
      closeDropdown();
    }
  };

  const closeDropdown = () => {
    setIsOpen(false);
    setStage("books");
    setSelectedBook(null);
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        closeDropdown();
      }
    };

    if (isOpen) {
      document.addEventListener("mousedown", handleClickOutside);
    }

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isOpen]);

  const currentBook = getBook(scrRef.book);

  return (
    <div className="bcv-selector" ref={dropdownRef}>
      <button onClick={() => setIsOpen(!isOpen)} className="bcv-selector-button">
        <span>
          {currentBook?.name} {scrRef.chapterNum}:{scrRef.verseNum}
        </span>
        {/* <ChevronDown className="ml-2 h-4 w-4" /> */}
      </button>

      {isOpen && (
        <div className="bcv-dropdown">
          <div className="bcv-dropdown-header">
            <h3>Select Reference</h3>
            <button className="bcv-close-button" onClick={closeDropdown}>
              ×
            </button>
          </div>

          {stage === "books" && (
            <>
              <div className="bcv-tabs">
                <button
                  className={`bcv-tab ${activeTab === "OT" ? "active" : ""}`}
                  onClick={() => setActiveTab("OT")}
                >
                  Old Testament
                </button>
                <button
                  className={`bcv-tab ${activeTab === "NT" ? "active" : ""}`}
                  onClick={() => setActiveTab("NT")}
                >
                  New Testament
                </button>
              </div>

              <div className="bcv-books-grid">
                {bibleData
                  .filter((b) => b.testament === activeTab)
                  .map((book) => (
                    <button
                      key={book.code}
                      onClick={() => handleBookClick(book.code)}
                      disabled={!isBookAvailable(book.code)}
                      className={`bcv-book-button ${
                        !isBookAvailable(book.code) ? "bcv-book-disabled" : ""
                      } ${scrRef.book === book.code ? "selected" : ""}`}
                    >
                      {book.name}
                    </button>
                  ))}
              </div>
            </>
          )}

          {stage === "chapters" && selectedBook && (
            <div className="bcv-chapters-container">
              <div className="bcv-chapters-header">
                <button onClick={() => setStage("books")} className="bcv-back-button">
                  {/* <ChevronLeft className="mr-1 h-4 w-4" /> */}
                  Back to Books
                </button>
                <h3 className="bcv-book-title">{getBook(selectedBook)?.name}</h3>
              </div>
              <div className="bcv-chapters-grid">
                {Array.from({ length: getChapterCount(selectedBook) }, (_, i) => i + 1).map(
                  (ch) => (
                    <button
                      key={ch}
                      onClick={() => handleChapterClick(ch)}
                      className="bcv-chapter-button"
                    >
                      {ch}
                    </button>
                  ),
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
